INSERT INTO `pasos` (`id`, `receta_id`, `orden`, `titulo`, `descripcion`, `timer`) VALUES (203,52,0,'Preparar duraznos','Escurre los duraznos y guarda el almíbar. Reserva 3–4 mitades para decorar. El resto va a la licuadora.',NULL),(204,52,1,'Licuar la crema','Licúa los duraznos, leche evaporada, condensada y queso crema hasta que esté liso. Prueba el dulzor antes de echar el limón. Agrega el limón poco a poco. En cuanto espese, para.',NULL),(205,52,2,'Primera capa','Capa fina de crema en el fondo del molde. Cubre todo.',NULL),(206,52,3,'Armar capas','Pasa cada galleta por el almíbar un segundo de cada lado. Capa de crema generosa encima. Repite: galletas → crema → galletas → crema. Termina con crema.',NULL),(207,52,4,'Decorar','Duraznos reservados cortados en láminas encima.',NULL),(208,52,5,'Refrigerar','Plástico pegado directo a la crema. Refri toda la noche mínimo.',14400),(209,53,0,'Rallar y exprimir','Ralla primero los 10g de limón antes de exprimir — una vez exprimido ya no puedes rallar. Reserva aparte. Exprime hasta obtener 80ml colado sin semillas.',NULL),(210,53,1,'Licuar la crema','Licúa queso crema, leche evaporada y condensada hasta que esté liso. Agrega el limón poco a poco probando. Para cuando tenga la acidez que quieres.',NULL),(211,53,2,'Primera capa','Capa fina de crema en el fondo del molde. Cubre todo.',NULL),(212,53,3,'Armar capas','Pasa cada galleta por la leche un segundo de cada lado. Capa de crema generosa encima. Repite: galletas → crema → galletas → crema. Termina con crema.',NULL),(213,53,4,'Decorar','Esparce la ralladura encima. No la licúes adentro — amarga.',NULL),(214,53,5,'Refrigerar','Plástico pegado directo a la crema. Refri toda la noche mínimo.',14400),(215,54,0,'Extraer la pulpa','Corta los maracuyás, saca la pulpa, licúa 2 segundos, cuela presionando bien. Necesitas ~180ml. Reserva pulpa con semillas de 2 maracuyás para la mermelada.',NULL),(216,54,1,'Licuar la crema','Licúa queso crema, leche evaporada y condensada. Agrega el jugo de maracuyá poco a poco probando. Sin limón — el maracuyá ya es el ácido.',NULL),(217,54,2,'Primera capa','Capa fina de crema en el fondo del molde. Cubre todo.',NULL),(218,54,3,'Armar capas','Pasa cada galleta por la leche un segundo de cada lado. Capa de crema generosa encima. Repite: galletas → crema → galletas → crema. Termina con crema.',NULL),(219,54,4,'Refrigerar','Plástico pegado directo a la crema. Refri toda la noche — el maracuyá necesita más tiempo que el durazno.',14400),(220,54,5,'Mermelada de decoración','Justo antes de servir: pulpa reservada + 40g azúcar en sartén a fuego medio revolviendo constantemente ~5 min hasta espesar. Deja enfriar completamente antes de poner encima.',300),(221,55,0,'Extraer la pulpa','Licúa 2 segundos, cuela presionando bien. Reserva 20g de semillas aparte.',NULL),(222,55,1,'Hervir la base','En olla de fondo grueso mezcla pulpa, azúcar y agua en frío. Lleva a fuego medio-alto revolviendo hasta que hierva.',NULL),(223,55,2,'Cocinar a fuego bajo','Baja a fuego medio-bajo. Agrega limón y semillas. Revuelve constantemente sin parar. En Puno tarda 5–8 min más de lo normal.',900),(224,55,3,'Test del punto','Cucharadita en platito frío al refri 2 min. Si no corre al inclinar, lista. Si corre, 3 min más y repite.',120),(225,55,4,'Reposar y guardar','Retira del fuego. Enfría 10 min en la olla. Pasa a frasco de vidrio limpio. Tapa solo cuando esté completamente fría. Dura 3 semanas en refri.',600),(226,56,0,'Hidratar gelatina','Espolvorea los 7g de gelatina sobre 45ml de agua fría. Deja reposar 5 min sin tocar — se pone esponjosa.',300),(227,56,1,'Extraer pulpa','Licúa los maracuyás 2 segundos, cuela presionando bien. Necesitas exactamente 180ml.',NULL),(228,56,2,'Mezclar base','Licúa la pulpa con la leche condensada hasta integrar. Agrega la vainilla. Reserva.',NULL),(229,56,3,'Disolver gelatina','Calienta la gelatina hidratada a baño maría hasta que se vuelva líquida — no hiervas. Deja enfriar 3 min. Tiene que estar tibia, no caliente.',NULL),(230,56,4,'Agregar gelatina','Agrega la gelatina tibia a la mezcla de maracuyá. Mezcla bien. Reserva.',NULL),(231,56,5,'Batir la crema','Bate la crema de leche fría a velocidad media — no alta. Para cuando forme picos blandos que caen solos. En Puno monta rápido, vigila.',NULL),(232,56,6,'Incorporar','Agrega la mezcla de maracuyá a la crema batida con movimientos envolventes — cuchara de abajo hacia arriba. No mezcles fuerte o pierdes el aire.',NULL),(233,56,7,'Refrigerar','Vierte en copas o vasitos con galleta molida en el fondo. Cubre con plástico. Refri toda la noche.',14400),(234,56,8,'Decorar','Mermelada de maracuyá fría encima al momento de servir.',NULL),(235,57,0,'Preparar la papaya','Pela la papaya, retira todas las semillas, corta en trozos. Necesitas 400g de pulpa limpia. La papaya varía mucho de dulzura — prueba antes de licuar.',NULL),(236,57,1,'Licuar la crema','Licúa papaya, leche evaporada, condensada y queso crema hasta que esté completamente liso. Prueba el dulzor — si está muy dulce no agregues más condensada. Agrega el limón poco a poco. La mezcla arranca más líquida que la de durazno pero espesa igual en el refri.',NULL),(237,57,2,'Primera capa','Capa fina de crema en el fondo del molde. Cubre todo.',NULL),(238,57,3,'Armar capas','Pasa cada galleta por la leche un segundo de cada lado. Capa de crema generosa encima. Repite: galletas → crema → galletas → crema. Termina con crema.',NULL),(239,57,4,'Decorar','Espolvorea canela molida encima como decoración.',NULL),(240,57,5,'Refrigerar','Plástico pegado directo a la crema. Refri toda la noche mínimo.',14400),(241,58,0,'Preparar la papaya','Pela, retira semillas y corta en cubos de 1–2cm.',NULL),(242,58,1,'Reposar con azúcar','Mezcla la papaya con el azúcar y el limón en la olla. Deja reposar 30 minutos sin cocinar — verás cómo suelta su propio jugo. No necesita agua.',1800),(243,58,2,'Hervir','Lleva a fuego medio revolviendo constantemente. Cuando hierva baja a fuego medio-bajo.',NULL),(244,58,3,'Cocinar','Cocina 30–40 min revolviendo constantemente — si paras se pega. Cuando empiece a espesar agrega la ralladura de limón. En Puno tarda 5–10 min más de lo normal.',2400),(245,58,4,'Test del punto','Cucharadita en platito frío al refri 2 min. Si no corre al inclinar, lista. Si corre, 3 min más y repite.',120),(246,58,5,'Guardar','Pasa a frasco de vidrio limpio. Tapa solo cuando esté completamente fría. Dura 3 semanas en refri.',NULL),(247,59,0,'Base de galletas','Tritura las galletas hasta que queden polvo fino. Mezcla con la mantequilla derretida hasta que parezca arena húmeda. Presiona firmemente en el fondo del molde forrado con plástico film. Mete al refri 20 min mientras preparas el relleno.',1200),(248,59,1,'Hidratar gelatina','Espolvorea los 10g de gelatina sobre 60ml de agua fría. Deja reposar 5 min sin tocar — se pone esponjosa.',300),(249,59,2,'Mezclar base del relleno','Bate el queso crema con la leche condensada hasta que esté completamente liso y sin grumos. Agrega el jugo de limón y la vainilla. Mezcla bien.',NULL),(250,59,3,'Disolver gelatina','Calienta la gelatina hidratada a baño maría hasta que se vuelva líquida — no hiervas. Deja enfriar 3 min. IMPORTANTE: mezcla primero la gelatina tibia con 2 cucharadas de la mezcla de queso, luego incorpora todo junto. Si la echas directa caliente se forman hilos.',NULL),(251,59,4,'Batir la crema','Bate la crema de leche fría a velocidad media hasta picos blandos. En Puno monta rápido con el frío — vigila, no te pases o se convierte en mantequilla.',NULL),(252,59,5,'Incorporar la crema','Incorpora la crema batida a la mezcla de queso con movimientos envolventes — de abajo hacia arriba con espátula. No mezcles fuerte o pierdes el aire.',NULL),(253,59,6,'Armar y refrigerar','Vierte el relleno sobre la base fría. Alisa la superficie. Plástico pegado directo a la crema. Refri mínimo 6 horas — toda la noche es mejor.',21600),(254,59,7,'Decorar y servir','Desmolda retirando el plástico. Pon la mermelada de maracuyá fría encima justo antes de servir — nunca tibia o derrite la crema.',NULL),(255,60,0,'Calentar la mezcla','Mezcla la leche entera con la crema de leche en una olla. Calienta a fuego bajo hasta llegar a ~80°C — en Puno eso es cuando empieza a humear fuerte pero sin hervir. Revuelve constantemente.',NULL),(256,60,1,'Agregar el ácido','Retira del fuego. Agrega el jugo de limón o vinagre poco a poco mientras mezclas suavemente. Verás que la mezcla se empieza a cortar y separar en grumos blancos y suero líquido. Si no se corta, agrega un poco más de limón.',NULL),(257,60,2,'Reposar','Deja reposar 15 minutos sin tocar para que la separación sea completa.',900),(258,60,3,'Colar','Vierte sobre una tela limpia (lienzo o paño fino) sobre un colador. Deja escurrir el suero 1–2 horas en el refri. Mientras más tiempo cuela, más firme queda.',3600),(259,60,4,'Sazonar','Agrega la sal al gusto y mezcla bien. Si quedó muy grumoso, bate un poco con batidora para suavizar. Guarda en frasco tapado en el refri. Dura 5–7 días.',NULL),(260,61,0,'Calentar la leche','Calienta la leche a 82°C — en Puno eso es justo cuando empieza a humear fuerte, antes de hervir. El objetivo es pasteurizar y desnaturalizar proteínas para que el yogur quede más espeso.',NULL),(261,61,1,'Enfriar','Retira del fuego. Deja enfriar hasta 43°C — al tacto se siente tibio pero no quema. En Puno con el frío ambiente esto es rápido, vigila con termómetro para no pasarte. Si baja de 38°C el cultivo no trabaja bien.',NULL),(262,61,2,'Agregar el cultivo','Mezcla 2 cucharadas del yogur comercial con un poco de leche tibia en un tazón pequeño hasta que esté liso. Luego incorpóralo al resto de la leche tibia y mezcla bien.',NULL),(263,61,3,'Fermentar','Tapa el recipiente y envuélvelo en una frazada o mételo al horno apagado con la luz encendida para mantener el calor. Deja reposar 8 horas sin mover ni abrir. En Puno el frío ambiente puede bajar la temperatura — la frazada es importante.',28800),(264,61,4,'Verificar','Después de 8 horas debe estar cuajado como gelatina suave y con un ligero olor ácido. Si está muy líquido, cubre y deja 2–4 horas más.',NULL),(265,61,5,'Colar para yogur griego','Vierte sobre una tela limpia en un colador. Mete al refri y deja colar 8 horas. El suero cae, lo que queda arriba es yogur griego. De 1L de leche obtienes ~400–450g de yogur griego.',28800),(266,62,0,'Sellar chuletas','Sellar en 2 tandas a fuego alto, 2-3 min por lado, en aceite vegetal.',180),(267,62,1,'Reposar carne','Reposar tapado (usar aluminio idealmente, no tapa de olla) mientras se hace la salsa.',300),(268,62,2,'Aromatizar fond','En la misma sartén, agregar mantequilla (14 g) y ajo para levantar los restos del sellado.',NULL),(269,62,3,'Deglasar','Añadir vino blanco (120 ml) y raspar el fondo de la sartén.',NULL),(270,62,4,'Reducir','Añadir fondo de carne o agua (60 ml) y vinagre tinto (5 ml), reducir a fuego medio.',NULL),(271,62,5,'Montar salsa','Fuera del fuego, incorporar mantequilla fría (42 g) en trozos, moviendo la sartén hasta emulsionar. Nunca montar con la sartén al fuego.',NULL),(272,62,6,'Sancochar papas','Papas con cáscara en olla a presión, ~5 min desde que silba. Verificar cocción con cuchillo.',300),(273,62,7,'Cocinar arroz','300 g arroz con 600 ml agua, fuego bajo tapado. Tiempo extendido por altitud.',1500),(274,63,0,'Lavar arroz','Lavar el arroz con agua aparte (no de los 600ml medidos). Paso de limpieza, opcional.',NULL),(275,63,1,'Remojar arroz','Remojar con agua o leche externa hasta cubrir todo.',NULL),(276,63,2,'Disolver panela','Poner el agua (600ml) en la olla, encender fuego. Agregar panela y canela en rama, disolver.',NULL),(277,63,3,'Cocinar arroz','Agregar el arroz remojado con su líquido. Tapar si quieres menos espeso, destapar si quieres más espeso.',1500),(278,63,4,'Calentar leche','Aparte, calentar la leche (600ml) con la crema de leche (125g).',NULL),(279,63,5,'Incorporar leche','Cuando el arroz esté cocido, retirar la canela en rama y agregar la mezcla de leche+crema.',NULL),(280,63,6,'Agregar pasas','Incorporar las pasas (50g).',NULL),(281,63,7,'Ajustar dulzor','Probar. Si el sustituto de panela no endulza suficiente, ajustar con azúcar extra (60g referencia).',NULL),(282,63,8,'Servir','Decorar con pasas extra, queso o canela en polvo si usas los opcionales.',NULL),(283,64,0,'Disolver maicena','Disolver la maicena (18g) en un poco de agua fría aparte, separada de los 600ml totales.',NULL),(284,64,1,'Disolver azúcar','Poner el resto del agua en la olla con el azúcar (90g), disolver.',NULL),(285,64,2,'Agregar zumo y gelatina','Añadir el zumo de limón (60-90ml). Agregar la gelatina sin sabor (4g) — NO combinar con gelatina de sabor, son excluyentes.',NULL),(286,64,3,'Espesar','Agregar la maicena ya disuelta. Llevar a hervor, bajar el fuego y cocinar unos minutos más.',NULL),(287,64,4,'Enfriar y moldear','Dejar enfriar. Llenar vasitos/moldes con la mezcla.',NULL),(288,64,5,'Primer congelado','Meter al congelador hasta que la superficie esté semi-firme (~1 hora).',3600),(289,64,6,'Agregar galleta y ralladura','Colocar encima la galleta María en trozos (opcional) y la ralladura de limón.',NULL),(290,64,7,'Congelado final','Volver a congelar hasta que esté completamente sólido.',NULL),(291,65,0,'Exprimir limones','Cortar los limones por la mitad y exprimir. Nunca licuar el limón entero — la cáscara/médula amarga.',NULL),(292,65,1,'Colar jugo','Colar el jugo con colador fino (quita semillas, deja pulpa fina si quieres).',NULL),(293,65,2,'Disolver azúcar','Disolver el azúcar en un poco de agua tibia (no hirviendo) hasta que quede transparente.',NULL),(294,65,3,'Mezclar','Mezclar jugo colado + almíbar + resto del agua.',NULL),(295,65,4,'Machacar hierbabuena','Machacar suave con la palma e incorporar.',NULL),(296,65,5,'Ajustar','Ajustar a gusto: más agua si ácido, más azúcar si falta dulzor.',NULL),(297,65,6,'Servir','Servir con hielo (200g).',NULL),(298,66,0,'Sazonar pollo','Sazonar y secar el pollo.',NULL),(299,66,1,'Sellar','Sellar el pollo en olla con aceite.',NULL),(300,66,2,'Reservar pollo','Sacar el pollo, reservar.',NULL),(301,66,3,'Sofrito','Sofreír cebolla → ajo → tomate → ají en ese orden.',NULL),(302,66,4,'Volver pollo','Regresar el pollo a la olla con el sofrito.',NULL),(303,66,5,'Guisar','Agua hasta cubrir. Hervir 20 min desde que rompe hervor.',1200),(304,66,6,'Cocinar arroz','Cocinar el arroz aparte usando el caldo del guiso.',NULL),(305,67,0,'Hervir carne','Hervir la carne en olla a presión con agua, sal, cebolla y ajo — 50-60 min desde que silba, despresurizar de forma natural 15 min.',3300),(306,67,1,'Reservar caldo','Sacar la carne, reservar el caldo.',NULL),(307,67,2,'Deshebrar','Deshebrar la carne con dos tenedores.',NULL),(308,67,3,'Sofrito','Sofreír cebolla → ajo → tomate.',NULL),(309,67,4,'Guisar carne','Echar la carne deshebrada al sofrito, mezclar, 5 min a fuego bajo.',300),(310,67,5,'Cocinar arroz','Cocinar el arroz con el caldo reservado de la carne.',NULL),(311,67,6,'Sancochar papas','Sancochar las papas aparte.',NULL),(312,68,0,'Disolver maicena','Disolver la maicena en el agua/leche fría.',NULL),(313,68,1,'Espesar','Llevar a fuego medio-bajo, revolviendo, hasta que espese, se vuelva translúcido y se despegue del fondo de la olla.',150),(314,68,2,'Enfriar','Dejar enfriar y cuajar.',NULL),(315,69,0,'Calar piña','Cortar la piña en cuadritos, cocinar en sartén con 25g de azúcar (de los 75g totales) hasta ablandar sin deshacer.',NULL),(316,69,1,'Licuar','Licuar con espesante + leche + azúcar restante (50g).',NULL),(317,69,2,'Congelar','Envasar y congelar.',NULL),(318,70,0,'Hacer mermelada','Cocinar fresa + azúcar (proporción ~4:1) en sartén 5-10 min, sin deshacer del todo.',450),(319,70,1,'Licuar','Licuar espesante + leche + azúcar + mermelada.',NULL),(320,70,2,'Congelar','Envasar y congelar.',NULL),(321,71,0,'Exprimir naranjas','Exprime las naranjas y cuela bien, sin dejar pulpa.',NULL),(322,71,1,'Verificar botella','Revisa que no tenga orificios, rayones, y que la tapa selle herméticamente.',NULL),(323,71,2,'Añadir jugo','Vierte el jugo colado dentro de la botella.',NULL),(324,71,3,'Disolver azúcar','Disuelve el azúcar en un poco de agua tibia y agrégala a la botella.',NULL),(325,71,4,'Agregar levadura','Pesa 1g exacto de levadura seca en báscula y agrégala.',NULL),(326,71,5,'Completar con agua','Completa con agua hervida fría hasta 1.5L, dejando 4 dedos vacíos en la parte superior de la botella.',NULL),(327,71,6,'Tapar y agitar','Tapa fuerte y agita suave.',30),(328,71,7,'Reposo a temperatura ambiente','Deja la botella a temperatura ambiente para que fermente. En Puno, por el frío, el proceso se alarga — ten paciencia.',NULL),(329,71,8,'Control de presión (cada 24h)','Abre levemente cada 24h para liberar presión. Si escuchas pop o silbido fuerte, cierra y espera 12-24h más antes de revisar de nuevo.',86400),(330,71,9,'Refrigerar','Cuando el pop sea fuerte, lleva inmediatamente al refrigerador para detener la fermentación.',NULL),(331,71,10,'Espera en frío','Espera antes de abrir para que se estabilice el gas.',9000),(332,71,11,'Abrir','Abre despacio y sobre el lavadero por si hay sobrepresión.',NULL),(333,72,0,'Limpieza','Quitar piel exterior y verificar que no quede la segunda membrana (pasa el dedo; si sientes algo elástico distinto a la carne, sigue ahí). Quitar \'uña\'/pico si tiene. Enjuagar bien las ventosas sin quitarlas.',NULL),(334,72,1,'Tratamiento con limón (opcional)','Bañar la pota cruda en jugo de limón, reposar, enjuagar y escurrir.',150),(335,72,2,'Cocción base','Cocinar en olla a presión, sin sal. Verificar con cuchillo que entre sin resistencia. Dejar reposar.',1500),(336,72,3,'Reposo post-cocción','Dejar reposar antes de manipular.',300),(337,72,4,'Corte','Cortar en rodajas finas transversales, 0.5-1 cm de grosor, perpendicular a la fibra.',NULL),(338,72,5,'Marinado','Batir los huevos con mostaza, ajo, comino, pimienta, sal y sillao (si usas). Meter la pota cortada y reposar como máximo.',600),(339,72,6,'Harina sazonada','Mezclar la harina con sal y pimienta antes de usarla — no olvidar este paso.',NULL),(340,72,7,'Rebozado','Sacar la pota del huevo y pasarla por la harina sazonada.',NULL),(341,72,8,'Fritura','Aceite bien caliente (prueba con una miga de pan). Freír en tandas pequeñas — la pota ya está cocida, solo se dora el rebozado. Escurrir en papel toalla.',90),(342,72,9,'Servir','Servir con yuca sancochada o papa dorada, sarsa criolla y limón.',NULL);
