INSERT INTO `errores` (`id`, `receta_id`, `descripcion`) VALUES (15,52,'La primera vez salió bien pero con un poco más de limón y condensada de lo planeado'),(16,54,'Primera vez los maracuyás no tenían suficiente jugo — buscar siempre con cáscara arrugada'),(17,55,'Primera vez usé mucha agua — la receta pide 60ml, no la misma cantidad que la pulpa'),(18,62,'Se usó tapa de olla en vez de papel aluminio para reposar la carne — funciona pero no es ideal (menos control de condensación).'),(19,62,'Si la carne sale correosa sin estar cruda: problema de corte contra la fibra o tipo de corte con tejido conectivo, no de tiempo/temperatura de sellado. No se corrige con más fuego.'),(20,64,'La galleta María no gustó como parte del postre — evaluar si vale la pena mantenerla en próximas tandas o quitarla del todo.'),(21,66,'Las papas se olvidaron por completo. Próxima vez: ponerlas a hervir aparte cuando falten 20 minutos para que todo llegue listo junto.'),(22,67,'Las papas se olvidaron otra vez. Próxima vez: ponerlas a hervir al mismo tiempo que arranca el sofrito, para que lleguen listas junto con lo demás.'),(23,71,'Botella con orificio: se perdió todo el gas'),(24,71,'Alguien abrió la botella: se perdió la carbonatación'),(25,71,'Se usó jugo de sandía ya fermentado: fermentación incontrolable y sabor malo'),(26,71,'Se puso 1g de levadura en vez de 0.5g en la versión de sandía: fermentación más rápida y menos control'),(27,71,'No se revisó cada 24h: sin control del proceso');
